
{{ config(materialized='table') }}

select
    order_id,
    order_item_id,
    product_id,
    seller_id,
    shipping_limit_date,

    price,
    freight_value,

    -- Revenue generated by the item, excluding freight
    price as item_revenue,

    -- Freight cost associated with the item
    freight_value as item_freight_cost,

    -- Item price plus freight
    price + freight_value as item_total_value

from {{ ref('stg_order_items') }}
